package com.srenterprises.entity; import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.math.*; import java.util.*;
@Entity @Table(name="order_items") public class OrderItem { @Id public UUID id=UUID.randomUUID(); @JsonIgnore @ManyToOne @JoinColumn(name="order_id") public CustomerOrder order; @ManyToOne @JoinColumn(name="product_id") public Product product; @Column(name="product_name") public String productName; public String sku; @Column(name="unit_price") public BigDecimal unitPrice; public int quantity; @Column(name="line_total") public BigDecimal lineTotal; }
